-- Fixes stale '28 jurisdictions/countries' text still sitting in D1's
-- translations table. The countryNames/regionNames blocks were
-- correctly migrated when Portugal and Finland were added, but the
-- count-related PROSE (brand.description, benefits.intro, etc.) was
-- only ever hand-edited directly in the live files during the earlier
-- '28->29' and '29->30' sitewide sweeps -- never written back to D1.
-- generate_files.py correctly regenerated files using what's actually
-- in D1, which faithfully reproduced the stale '28' -- this migration
-- corrects the actual source of truth so this doesn't happen again.

UPDATE translations SET value = 'A living tracker of e-invoicing and digital reporting mandates across 30 countries — EU-wide ViDA rules, national CTC systems, and everything in between. Each entry shows the deadline, what you need to do about it, and a direct link to the official government portal, so you can go from "is this relevant to us?" to "here''s what to action" in one page.' WHERE namespace = 'tracker' AND key = 'brand.description' AND lang = 'en';
UPDATE translations SET value = 'Un seguimiento actualizado de los mandatos de facturación electrónica y reporte digital en 30 países — normas de ViDA a nivel de la UE, sistemas nacionales de CTC, y todo lo demás. Cada entrada muestra la fecha límite, lo que debe hacer al respecto, y un enlace directo al portal oficial del gobierno, para que pueda pasar de "¿esto nos afecta?" a "esto es lo que hay que hacer" en una sola página.' WHERE namespace = 'tracker' AND key = 'brand.description' AND lang = 'es';
UPDATE translations SET value = 'Ein laufend aktualisierter Überblick über E-Invoicing- und digitale Meldepflichten in 30 Ländern — EU-weite ViDA-Regeln, nationale CTC-Systeme und alles dazwischen. Jeder Eintrag zeigt die Frist, was konkret zu tun ist, und einen direkten Link zum offiziellen Regierungsportal — damit Sie in einem einzigen Blick von "betrifft uns das?" zu "das müssen wir tun" kommen.' WHERE namespace = 'tracker' AND key = 'brand.description' AND lang = 'de';
UPDATE translations SET value = 'Un suivi actualisé en continu des obligations de facturation électronique et de télédéclaration dans 30 pays — règles ViDA à l''échelle de l''UE, systèmes nationaux de CTC, et tout ce qui se trouve entre les deux. Chaque entrée indique l''échéance, ce qu''il faut faire, et un lien direct vers le portail officiel du gouvernement, pour passer de "est-ce que cela nous concerne ?" à "voici ce qu''il faut faire" en une seule page.' WHERE namespace = 'tracker' AND key = 'brand.description' AND lang = 'fr';
UPDATE translations SET value = 'E-invoicing thresholds, wave numbers, and go-live dates change constantly — often with little public notice. Subscribe once, and every government update or announcement across the 30 jurisdictions we track lands in your inbox automatically, in plain language, before it catches your team off guard.' WHERE namespace = 'subscribe' AND key = 'benefits.intro' AND lang = 'en';
UPDATE translations SET value = 'Tell us which of the 30 jurisdictions matter to your business, and your monthly notification email tells you specifically whether they came up — or get the full global digest if you''d rather see everything.' WHERE namespace = 'subscribe' AND key = 'benefits.item2.body' AND lang = 'en';
UPDATE translations SET value = 'Optional — leave everything unchecked and we''ll send the full monthly digest covering all 30 jurisdictions.' WHERE namespace = 'subscribe' AND key = 'card.countriesHint' AND lang = 'en';
UPDATE translations SET value = 'the full digest (all 30 jurisdictions)' WHERE namespace = 'subscribe' AND key = 'confirm.fullDigest' AND lang = 'en';
UPDATE translations SET value = 'Los umbrales de facturación electrónica, los números de ola y las fechas de puesta en marcha cambian constantemente — a menudo con poco aviso público. Suscríbase una vez y cada actualización o anuncio gubernamental de las 30 jurisdicciones que seguimos llegará automáticamente a su bandeja de entrada, en lenguaje sencillo, antes de que sorprenda a su equipo.' WHERE namespace = 'subscribe' AND key = 'benefits.intro' AND lang = 'es';
UPDATE translations SET value = 'Díganos cuáles de las 30 jurisdicciones importan a su negocio, y su correo de notificación mensual le dirá específicamente si aparecieron — o reciba el resumen global completo si prefiere verlo todo.' WHERE namespace = 'subscribe' AND key = 'benefits.item2.body' AND lang = 'es';
UPDATE translations SET value = 'Opcional — deje todo sin marcar y le enviaremos el resumen mensual completo de las 30 jurisdicciones.' WHERE namespace = 'subscribe' AND key = 'card.countriesHint' AND lang = 'es';
UPDATE translations SET value = 'el resumen completo (las 30 jurisdicciones)' WHERE namespace = 'subscribe' AND key = 'confirm.fullDigest' AND lang = 'es';
UPDATE translations SET value = 'E-Invoicing-Schwellenwerte, Wellen-Nummern und Stichtage ändern sich ständig — oft mit wenig öffentlicher Vorankündigung. Einmal abonniert, landet jede Regierungsaktualisierung oder -ankündigung aus den 30 von uns erfassten Rechtsordnungen automatisch in Ihrem Posteingang, in klarer Sprache, bevor sie Ihr Team überrascht.' WHERE namespace = 'subscribe' AND key = 'benefits.intro' AND lang = 'de';
UPDATE translations SET value = 'Teilen Sie uns mit, welche der 30 Rechtsordnungen für Ihr Unternehmen relevant sind, und Ihre monatliche Benachrichtigungs-E-Mail sagt Ihnen konkret, ob sie vorkamen — oder erhalten Sie den vollständigen globalen Digest, wenn Sie lieber alles sehen möchten.' WHERE namespace = 'subscribe' AND key = 'benefits.item2.body' AND lang = 'de';
UPDATE translations SET value = 'Optional — lassen Sie alles unmarkiert, und wir senden Ihnen den vollständigen monatlichen Digest für alle 30 Rechtsordnungen.' WHERE namespace = 'subscribe' AND key = 'card.countriesHint' AND lang = 'de';
UPDATE translations SET value = 'den vollständigen Digest (alle 30 Rechtsordnungen)' WHERE namespace = 'subscribe' AND key = 'confirm.fullDigest' AND lang = 'de';
UPDATE translations SET value = 'Les seuils de facturation électronique, les numéros de vague et les dates de mise en service changent constamment — souvent avec peu de préavis public. Abonnez-vous une fois, et chaque mise à jour ou annonce gouvernementale des 30 juridictions que nous suivons arrive automatiquement dans votre boîte de réception, en langage clair, avant qu''elle ne prenne votre équipe au dépourvu.' WHERE namespace = 'subscribe' AND key = 'benefits.intro' AND lang = 'fr';
UPDATE translations SET value = 'Indiquez-nous lesquelles des 30 juridictions concernent votre entreprise, et votre e-mail de notification mensuel vous dira précisément si elles ont été concernées — ou recevez la synthèse mondiale complète si vous préférez tout voir.' WHERE namespace = 'subscribe' AND key = 'benefits.item2.body' AND lang = 'fr';
UPDATE translations SET value = 'Facultatif — laissez tout décoché et nous vous enverrons la synthèse mensuelle complète couvrant les 30 juridictions.' WHERE namespace = 'subscribe' AND key = 'card.countriesHint' AND lang = 'fr';
UPDATE translations SET value = 'la synthèse complète (les 30 juridictions)' WHERE namespace = 'subscribe' AND key = 'confirm.fullDigest' AND lang = 'fr';

