-- files against the live repo copies, which already have the correct count).
UPDATE translations SET value = 'This is a <strong>starting set of verified links</strong>, not a complete map of all 30 tracked jurisdictions. Every link below was checked directly against the named government/authority''s own website. Several countries in this tracker don''t run a public accreditation registry at all — see the note in Section 3 before assuming one exists.' WHERE namespace = 'edu-certified-providers' AND key = 'statusBanner.text' AND lang = 'en';
UPDATE translations SET value = 'The Deep Dives menu covers exact registration steps, technical specifications, and penalties for each of the 30 jurisdictions tracked here.' WHERE namespace = 'edu-certified-providers' AND key = 'sec5.card3.body' AND lang = 'en';
UPDATE translations SET value = 'Este es un <strong>conjunto inicial de enlaces verificados</strong>, no un mapa completo de las 30 jurisdicciones seguidas. Cada enlace de abajo se comprobó directamente en el propio sitio web del gobierno/autoridad mencionado. Varios países de este seguimiento simplemente no gestionan un registro público de acreditación — vea la nota de la Sección 3 antes de asumir que existe uno.' WHERE namespace = 'edu-certified-providers' AND key = 'statusBanner.text' AND lang = 'es';
UPDATE translations SET value = 'El menú de análisis por país cubre los pasos exactos de registro, las especificaciones técnicas y las sanciones de cada una de las 30 jurisdicciones seguidas aquí.' WHERE namespace = 'edu-certified-providers' AND key = 'sec5.card3.body' AND lang = 'es';
UPDATE translations SET value = 'Dies ist ein <strong>erster Satz verifizierter Links</strong>, keine vollständige Übersicht aller 30 erfassten Rechtsordnungen. Jeder Link unten wurde direkt anhand der eigenen Website der genannten Regierung/Behörde geprüft. Mehrere Länder in diesem Tracker führen überhaupt kein öffentliches Akkreditierungsregister — siehe den Hinweis in Abschnitt 3, bevor Sie annehmen, dass eines existiert.' WHERE namespace = 'edu-certified-providers' AND key = 'statusBanner.text' AND lang = 'de';
UPDATE translations SET value = 'Das Menü der Länderanalysen behandelt die genauen Registrierungsschritte, technischen Spezifikationen und Sanktionen für jede der 30 hier erfassten Rechtsordnungen.' WHERE namespace = 'edu-certified-providers' AND key = 'sec5.card3.body' AND lang = 'de';
UPDATE translations SET value = 'Il s''agit d''un <strong>premier ensemble de liens vérifiés</strong>, pas d''une cartographie complète des 30 juridictions suivies. Chaque lien ci-dessous a été vérifié directement sur le site propre du gouvernement/de l''autorité mentionné. Plusieurs pays de ce suivi ne gèrent tout simplement aucun registre public d''agrément — consultez la remarque de la section 3 avant de supposer qu''il en existe un.' WHERE namespace = 'edu-certified-providers' AND key = 'statusBanner.text' AND lang = 'fr';
